// Execution only. The complete registry is declared before this module.
function createSource(definition) {
  const aliases = Object.fromEntries(Object.entries(definition.aliases || {}).map(([ruleID, siteID]) => [siteID, ruleID]));
  const sites = definition.siteIDs.map(id => {
    const rule = websiteRules[id];
    const catalog = rule.catalog ? {
      filters: rule.catalog.filters.map(publicCatalogFilter),
      searchFilters: rule.catalog.searchFilters.map(publicCatalogFilter),
      ...(rule.catalog.filters.some(filter => filter.optionsSource) ? {dynamicFilters: true} : {})
    } : undefined;
    return {id: definition.aliases?.[id] || id, name: rule.name, kind: rule.kind,
      homepage: rule.homepage, group: websiteGroups[rule.group], capabilities: rule.capabilities, ...(catalog ? {catalog} : {})};
  });
  const drives = definition.driveIDs.map(id => {
    const {name, root, authentication} = driveRules[id];
    return {id, name, root, authentication};
  });
  const domains = Array.from(new Set(definition.siteIDs.flatMap(id => websiteRules[id].domains)
    .concat(drives.flatMap(drive => drive.authentication.domains))));
  function siteInput(input) {
    return aliases[input.siteID] ? {...input, siteID: aliases[input.siteID]} : input;
  }
  return {
    manifest: {apiVersion: definition.apiVersion, id: definition.id, name: definition.name, version: definition.version,
      domains, sites, drives, settings: definition.settings},
    home(input) {return websiteHome(siteInput(input));},
    catalog(input) {return websiteCatalog(siteInput(input));},
    catalogFilters(input) {return websiteCatalogFilters(siteInput(input));},
    search(input) {return websiteSearch(siteInput(input));},
    detail(input) {return websiteDetail(siteInput(input));},
    chapters(input) {return novelChapters(siteInput(input));},
    content(input) {return websiteContent(siteInput(input));},
    driveList(input) {return driveList(input);},
    driveResolve(input) {return driveResolve(input);},
    driveShareList(input) {return driveShareList(input);},
    driveTransfer(input) {return driveTransfer(input);},
    driveTransferStatus(input) {return driveTransferStatus(input);}
  };
}
function website(id) {
  const value = websiteRules[id];
  if (!value) throw new Error('Unknown site');
  return value;
}
function book(site, row, base) {
  const url = host.url(row.detailURL || row.link || '', base);
  if (!row.title || !url) return null;
  return {sourceID:site.id,title:row.title,author:(row.author||'').replace(/^作者：/,''),
    detailURL:url,coverURL:host.url(row.coverURL || row.cover || '',base),summary:row.summary||'',
    ...(row.attributes?.length ? {attributes: row.attributes} : {})};
}
function uniqueBooks(site, rows, base) {
  const seen = new Set();
  return rows.map(row => book(site,row,base)).filter(row => row && !seen.has(row.detailURL) && seen.add(row.detailURL));
}
function initialState(html) {
  const marker = html.indexOf('window.__INITIAL_STATE__');
  if (marker < 0) throw new Error('Missing initial state');
  const start = html.indexOf('{',marker);
  let depth=0,quote='',escape=false;
  for(let i=start;i<html.length;i++) {
    const c=html[i];
    if(quote) { if(escape)escape=false; else if(c==='\\')escape=true; else if(c===quote)quote=''; }
    else if(c==='"'||c==="'")quote=c;
    else if(c==='{')depth++;
    else if(c==='}' && --depth===0)return JSON.parse(html.slice(start,i+1));
  }
  throw new Error('Incomplete initial state');
}

function biqugeDetail(input,site,response,chapters) {
  const fields=host.select(response.body,'html',site.detail.fields)[0];
  if(!fields?.title)throw new Error('Missing book details');
  const attributes=site.detail.attributes.filter(attribute=>fields[attribute.field])
    .map(attribute=>({name:attribute.name,value:fields[attribute.field]}));
  return {book:{...input.book,title:fields.title,author:fields.author,summary:fields.summary,
    coverURL:host.url(fields.cover,response.url),attributes},chapters};
}

function biqugeChapterAddress(url,rule) {
  return String(url).match(rule.chapterPattern);
}

function biqugeContent(input,site) {
  const chapter=biqugeChapterAddress(input.chapter.url,site.reading);
  if(!chapter)throw new Error('Invalid chapter address');
  const seen=new Set(),paragraphs=[];
  let url=input.chapter.url,title=input.chapter.title;
  // A website page is only part of a chapter. Never treat the next chapter as a continuation.
  for(let page=0;page<12;page++) {
    if(seen.has(url))throw new Error('Chapter pagination loop');
    seen.add(url);
    const response=host.get(url),content=host.content(response.body,site.reading,response.url);
    if(page===0 && content.title)title=content.title;
    for(const paragraph of content.paragraphs) {
      const text=paragraph.trim(),normalized=text.normalize('NFKC').replace(/\s+/g,'');
      if(!text || site.reading.ignoredParagraphs.some(pattern=>pattern.test(normalized)))continue;
      paragraphs.push(text);
    }
    const link=host.select(response.body,site.reading.next,{url:{selector:'',attribute:'href'}})[0];
    const next=link?.url?host.url(link.url,response.url):null,continuation=biqugeChapterAddress(next,site.reading);
    if(!continuation || continuation[1]!==chapter[1] || !continuation[2]) {
      if(response.body.includes(site.reading.continuationNotice))throw new Error('Missing chapter continuation');
      if(!paragraphs.length)throw new Error('Missing chapter content');
      return {title,paragraphs};
    }
    url=next;
  }
  throw new Error('Chapter exceeds the page request limit');
}


function websiteHome(input) {
  const site=website(input.siteID),rule=site.home;
  if(rule.type==='catalog') {
    const page=websiteCatalog(input);
    return [{id:rule.id,title:page.title||rule.title,tabTitle:rule.tabTitle,books:page.books}];
  }
  const response=sourceRequest(site,rule.request,catalogParameters(site,input,false));
  if(rule.type==='fanqie') {
    const data=initialState(response.body).home;
    return rule.sections.map(section=>({id:section.id,title:section.title,tabTitle:section.tabTitle,
      books:uniqueBooks(site,(data[section.key]||[]).map(book=>({title:book.bookName,link:sourceTemplate(rule.detailURL,{homepage:site.homepage,bookID:book.bookId}),
        author:book.author,cover:book.thumbUri,summary:book.abstract})),response.url)}));
  }
  if(rule.type==='mox')return [{id:rule.id,title:rule.title,tabTitle:rule.tabTitle,books:moxBooks(site,response)}];
  return rule.sections.map(section=>({id:section.id,title:section.title,tabTitle:section.tabTitle,
    books:catalogBooks(site,response,section.rows)}));
}

function websiteSearch(input) {
  const site=website(input.siteID);
  if(site.search?.handler)return site.search.handler(input,site);
  if(site.search) {
    const parameters=catalogParameters(site,input,true);
    const response=sourceRequest(site,site.search.request,parameters);
    if(site.search.expectedStatus&&response.status!==site.search.expectedStatus)throw new Error(site.search.error);
    return catalogBooks(site,response,site.search.rows);
  }
  if(Number(input.page||1)!==1)return [];
  return websiteCatalog(input).books;
}

function websiteDetail(input) {
  const site=website(input.siteID);
  if(site.detail?.handler)return site.detail.handler(input,site);
  if(site.reading?.engine==='paged')return novelDetail(input,site);
  return htmlNovelDetail(input,site);
}

function websiteContent(input) {
  const site=website(input.siteID);
  if(site.reading?.handler)return site.reading.handler(input,site);
  if(site.reading?.engine==='paged')return novelContent(input,site);
  const response=host.get(input.chapter.url);
  return host.content(response.body,site.reading,response.url);
}
function htmlNovelDetail(input,site) {
  const rule=site.reading;
  if(!rule)throw new Error('No online chapters');
  let response=host.get(input.book.detailURL);
  if(rule.catalogLink) {
    const row=host.select(response.body,'html',{link:rule.catalogLink})[0];
    if(!row || !row.link)throw new Error('Missing chapter directory');
    response=host.get(host.url(row.link,response.url));
  }
  const seen=new Set();
  const chapters=host.select(response.body,rule.chapterItems,{title:rule.chapterTitle,link:rule.chapterLink,
    locked:{selector:rule.lockedSelector||'.nori-none',attribute:'class'}}).map(row=>({title:row.title,
      url:host.url(row.link,response.url),isLocked:!!row.locked})).filter(c=>c.title && c.url && !seen.has(c.url) && seen.add(c.url));
  if(!chapters.length)throw new Error('Missing chapters');
  if(site.parser==='biquge')return biqugeDetail(input,site,response,chapters);
  return {book:input.book,chapters};
}
function literalCalls(html,marker) {
  const calls=[];let offset=0;
  while((offset=html.indexOf(marker,offset))>=0) {
    const start=offset+marker.length;let depth=1,quote='',escaped=false,end=start;
    for(;end<html.length;end++) {
      const c=html[end];
      if(quote) { if(escaped)escaped=false;else if(c==='\\')escaped=true;else if(c===quote)quote=''; }
      else if(c==='"'||c==="'")quote=c;
      else if(c==='(')depth++;
      else if(c===')' && --depth===0)break;
    }
    if(depth!==0)break;
    calls.push(html.slice(start,end));offset=end+1;
  }
  return calls;
}


function gutenbergDetail(input,site) {
  const response=host.get(input.book.detailURL),rule=site.detail.resources;
  const rows=host.select(response.body,rule.items,rule.fields);
  if(!rows.length)throw new Error('No supported book file');
  return {book:input.book,chapters:[],resources:[{title:rule.title,kind:'download',filename:rule.filename,
    url:host.url(rows[0].link,response.url)}]};
}
function kgbookDetail(input,site) {
  const response=host.get(input.book.detailURL);
  const fields=host.select(response.body,site.detail.items,site.detail.fields)[0];
  if(!fields?.title)throw new Error('Missing book details');
  const attributes=[];let author='';
  for(const item of host.select(response.body,site.detail.attributes.items,site.detail.attributes.fields)) {
    const colon=item.text.indexOf('：');
    if(colon<0)continue;
    const name=item.text.slice(0,colon).trim();let value=item.text.slice(colon+1).trim();
    if(name==='作者') {author=value;continue;}
    if(name==='星级' && !value) {
      const rating=item.rating.match(/\/(\d)star\./);if(rating)value=rating[1]+' / 5';
    }
    if(value)attributes.push({name,value});
  }
  const title=fields.title,seen=new Set();
  const resources=host.select(response.body,site.detail.resources.items,site.detail.resources.fields)
    .map(row=>{
      const match=row.title.match(/(epub|mobi|azw3|txt|pdf|cbz|zip)/i),url=host.url(row.url,response.url);
      if(!match || !url || seen.has(url))return null;
      seen.add(url);const format=match[1].toLowerCase();
      return {title:format.toUpperCase(),kind:'download',filename:title.replace(/[\\/]/g,'_')+'.'+format,url};
    }).filter(Boolean);
  if(!resources.length)throw new Error('No book files');
  return {book:{...input.book,title,author,summary:fields.summary,coverURL:host.url(fields.cover,response.url),attributes},chapters:[],resources};
}

function fanqieSearch(input,site) {
  const parameters=catalogParameters(site,input,true),rule=site.search;
  const response=host.browserRequest({pageURL:sourceTemplate(rule.pageURL,parameters),
    url:sourceTemplate(rule.request.url,parameters)});
  if(response.status!==200||!response.body.trim())throw new Error('NORI_SEARCH_UNAVAILABLE');
  const result=JSON.parse(response.body);
  if(result.code!==0||!Array.isArray(result.data?.search_book_data_list))throw new Error('NORI_SEARCH_UNAVAILABLE');
  // Search metadata uses per-response font glyphs; public detail HTML provides Unicode.
  const ids=[...new Set(result.data.search_book_data_list.map(book=>String(book.book_id||'')).filter(id=>/^\d+$/.test(id)))].slice(0,rule.limit);
  return uniqueBooks(site,ids.map(id=>{
    const detail=host.get(sourceTemplate(rule.detailURL,{...parameters,bookID:id})),data=initialState(detail.body).page;
    if(!data?.bookName||String(data.bookId)!==id)throw new Error('NORI_SEARCH_UNAVAILABLE');
    return {title:data.bookName,author:data.author,link:sourceTemplate(rule.detailURL,{...parameters,bookID:id}),cover:data.thumbUrl||data.thumbUri,summary:data.abstract||''};
  }),site.homepage);
}

function kuaikanSearch(input,site) {
  const parameters=catalogParameters(site,input,true);
  const response=sourceRequest(site,site.search.request,parameters);
  const result=JSON.parse(response.body),topics=result.data?.topics?.hit;
  if(response.status!==200||result.code!==200||!Array.isArray(topics))throw new Error('NORI_SEARCH_UNAVAILABLE');
  return uniqueBooks(site,topics.map(book=>({title:book.title,author:book.user?.nickname||'',link:sourceTemplate(site.search.detailURL,{...parameters,bookID:book.id}),
    cover:book.vertical_image_url||book.cover_image_url,summary:book.description||''})),site.homepage);
}

function moxBooks(site,response) {
  const rows=[];
  for(const argumentsText of literalCalls(response.body,site.home.literalMarker)) {
    const strings=(argumentsText.match(/"(?:\\.|[^"\\])*"/g)||[]).map(value=>JSON.parse(value));
    if(strings.length>=14&&strings[0]==='div_info_')rows.push({title:strings[10].replace(/<[^>]*>/g,''),
      author:strings[11].replace(/<[^>]*>/g,''),link:strings[2],cover:strings[3]});
  }
  return uniqueBooks(site,rows,response.url);
}

function moxSearch(input,site) {
  const parameters=catalogParameters(site,input,true);
  const response=sourceRequest(site,site.search.request,parameters);
  if(response.url.includes('login')||response.body.includes('ipt_email'))throw new Error('NORI_SITE_LOGIN_REQUIRED');
  return moxBooks(site,response);
}
// Nuxt's hydration payload is a literal object with shared literal parameters.
// Parse that data grammar; never evaluate a website's scripts or function calls.
function literalReader(text,variables=Object.create(null)) {
  let offset=0;
  const identifiers=/[A-Za-z_$][\w$]*/y,numbers=/-?\d+(?:\.\d+)?(?:[eE][+-]?\d+)?/y;
  function skip(){while(offset<text.length && text.charCodeAt(offset)<=32)offset++;}
  function expect(token){skip();if(text.slice(offset,offset+token.length)!==token)throw new Error('Invalid serialized data');offset+=token.length;}
  function identifier(){skip();identifiers.lastIndex=offset;const m=identifiers.exec(text);if(!m)throw new Error('Invalid data key');offset+=m[0].length;return m[0];}
  function value(depth=0) {
    if(depth>64)throw new Error('Serialized data is too deep');
    skip();const c=text[offset];
    if(c==='"') {
      const start=offset++;let escaped=false;
      while(offset<text.length){const next=text[offset++];if(escaped)escaped=false;else if(next==='\\')escaped=true;else if(next==='"')return JSON.parse(text.slice(start,offset));}
      throw new Error('Incomplete data string');
    }
    if(c==='{' || c==='[') {
      offset++;const object=c==='{',out=object?Object.create(null):[],end=object?'}':']';skip();
      while(text[offset]!==end) {
        let key;if(object){key=text[offset]==='"'?value(depth+1):identifier();expect(':');}
        const item=value(depth+1);if(object)out[key]=item;else out.push(item);skip();
        if(text[offset]!==',')break;offset++;skip();
      }
      expect(end);return out;
    }
    numbers.lastIndex=offset;const number=numbers.exec(text);
    if(number){offset+=number[0].length;return Number(number[0]);}
    const key=identifier();
    if(key==='true')return true;if(key==='false')return false;if(key==='null')return null;
    if(key==='Array'){expect('(');const length=value(depth+1);expect(')');if(!Number.isInteger(length)||length<0||length>10000)throw new Error('Invalid data array');return Array(length);}
    if(Object.hasOwn(variables,key))return variables[key];
    throw new Error('Unsupported serialized value');
  }
  return {value,expect,identifier,done(){skip();return offset===text.length;}};
}

function kuaikanState(html) {
  const start=html.indexOf('window.__NUXT__=');
  if(start<0)throw new Error('Missing comic data');
  const end=html.indexOf('</script>',start),payload=html.slice(start,end);
  const header=payload.match(/^window\.__NUXT__=\(function\(([^)]*)\)\s*\{/);
  const call=payload.lastIndexOf('}('),returned=payload.indexOf('return ',header?.[0].length);
  if(!header || call<0 || returned<0)throw new Error('Unsupported comic data');
  const argumentsReader=literalReader(payload.slice(call+1).replace(/\)\);?\s*$/,'')),variables=Object.create(null);
  argumentsReader.expect('(');
  const names=header[1].split(',');
  for(let index=0;index<names.length;index++) {if(index)argumentsReader.expect(',');variables[names[index]]=argumentsReader.value();}
  if(!argumentsReader.done())throw new Error('Invalid comic arguments');
  const assignments=payload.slice(header[0].length,returned).trim();
  for(const assignment of assignments.split(';').filter(s=>s.trim())) {
    const match=assignment.trim().match(/^([\w$]+)(?:\.([\w$]+)|\[(\d+)\])=(.*)$/s);
    if(!match || !variables[match[1]] || typeof variables[match[1]]!=='object')throw new Error('Unsupported shared data');
    if(match[3] && Number(match[3])>=10000)throw new Error('Invalid shared index');
    const reader=literalReader(match[4],variables);variables[match[1]][match[2]??match[3]]=reader.value();
    if(!reader.done())throw new Error('Invalid shared data');
  }
  return literalReader(payload.slice(returned+7,call),variables).value();
}

function kuaikanDetail(input,site) {
  const state=kuaikanState(host.get(input.book.detailURL).body),data=state.data?.[0];
  const topic=data?.res?.data?.topic_info||data?.topicInfo;
  const rows=topic?.comics||data?.comics;
  if(!topic?.title || !rows?.length)throw new Error('Missing comic catalog');
  const seen=new Set(),chapters=rows.map(chapter=>({title:chapter.title,url:sourceTemplate(site.reading.chapterURL,{homepage:site.homepage,chapterID:chapter.id}),
    isLocked:!!(chapter.locked || chapter.need_vip || chapter.is_vip_exclusive || (chapter.is_pay_comic && !chapter.is_free && !chapter.has_bought))}))
    .filter(c=>c.title && !seen.has(c.url) && seen.add(c.url));
  return {book:{...input.book,title:topic.title,author:topic.user?.nickname||input.book.author,summary:topic.description||'',
    coverURL:topic.vertical_image_url||topic.cover_image_url,attributes:[{name:'话数',value:String(chapters.length)}]},chapters};
}

function kuaikanContent(input) {
  if(input.chapter.isLocked)throw new Error('Authorization required');
  const data=kuaikanState(host.get(input.chapter.url).body).data?.[0];
  const body=data?.res?.data,info=body?.comic_info||data?.comicInfo;
  if(!info || info.locked || info.need_vip || info.is_vip_exclusive || (info.is_pay_comic && !info.is_free && !info.has_bought))throw new Error('Authorization required');
  // The server renders only the first two <img> tags. The full ordered list is in res.data.
  const rows=info.comic_images||body?.comic_images||body?.images;
  if(!rows?.length)throw new Error('Missing comic images');
  return {title:info.title||input.chapter.title,images:rows.map(image=>({url:image.url1280||image.url,
    width:image.width1280||image.width,height:image.height}))};
}

function qqComicDetail(input,site) {
  const response=host.get(input.book.detailURL),html=response.body;
  const fields=host.select(html,'html',site.detail.fields)[0];
  const seen=new Set(),chapters=host.select(html,site.detail.chapters.items,site.detail.chapters.fields)
    .map(row=>({title:row.title,url:host.url(row.link,response.url),isLocked:!row.free}))
    .filter(c=>c.title && c.url && !seen.has(c.url) && seen.add(c.url));
  if(!fields?.title || !chapters.length)throw new Error('Missing comic catalog');
  return {book:{...input.book,title:fields.title,author:fields.author.replace(/^作者[:：]\s*/,''),summary:fields.summary,
    coverURL:host.url(fields.cover,response.url),attributes:[{name:'话数',value:String(chapters.length)}]},chapters};
}

function comicArithmetic(text) {
  text=text.replace(/document\.getElementsByTagName\(['"]html['"]\)/g,'1')
    .replace(/document\.children|window\.Array/g,'1')
    .replace(/(['"])([0-9A-Za-z])\1\.charCodeAt\(\s*(?:0)?\s*\)/g,(_,quote,c)=>String(c.charCodeAt(0)))
    .replace(/Math\.pow/g,'P').replace(/Math\.round/g,'R').replace(/Math\.floor/g,'F').replace(/parseInt/g,'I');
  if(text.length>64 || !/^[\d\s!~&+*/().,PRFI-]+$/.test(text))throw new Error('Invalid numeric data');
  let at=0;function skip(){while(at<text.length && text.charCodeAt(at)<=32)at++;}
  function unary(){skip();if('PRFI'.includes(text[at]||' ')){const fn=text[at++];if(text[at++]!=='(')throw new Error('Invalid numeric function');const a=bitwise();
      if(fn!=='P'){if(text[at++]!==')')throw new Error('Invalid numeric function');return fn==='R'?Math.round(a):fn==='F'?Math.floor(a):Math.trunc(a);}
      if(text[at++]!==',')throw new Error('Invalid numeric power');const b=bitwise();if(text[at++]!==')'||Math.abs(a)>10000||Math.abs(b)>16)throw new Error('Invalid numeric power');return Math.pow(a,b);}
    if(text[at]==='~'){at++;return ~unary();}
    if(text[at]==='!'){at++;return Number(!unary());}if(text[at]==='+'){at++;return unary();}
    if(text[at]==='-'){at++;return -unary();}if(text[at]==='('){at++;const v=bitwise();skip();if(text[at++]!==')')throw new Error('Invalid numeric group');return v;}
    const m=text.slice(at).match(/^(?:\d+(?:\.\d*)?|\.\d+)/);if(!m)throw new Error('Invalid number');at+=m[0].length;return Number(m[0]);}
  function product(){let v=unary();skip();while(text[at]==='*'||text[at]==='/'){const op=text[at++],r=unary();v=op==='*'?v*r:v/r;skip();}return v;}
  function sum(){let v=product();skip();while(text[at]==='+'||text[at]==='-'){const op=text[at++],r=product();v=op==='+'?v+r:v-r;skip();}return v;}
  function bitwise(){let v=sum();skip();while(text[at]==='&'){at++;v=v&sum();skip();}return v;}
  const value=bitwise();skip();if(at!==text.length||!Number.isFinite(value))throw new Error('Invalid numeric expression');return value;
}

function comicBase64(text) {
  const alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/',bytes=[];
  if(!/^[A-Za-z0-9+/]*={0,2}$/.test(text))throw new Error('Invalid image payload');
  let buffer=0,bits=0;
  for(const c of text.replace(/=+$/,'')){buffer=(buffer<<6)|alphabet.indexOf(c);bits+=6;if(bits>=8){bits-=8;bytes.push((buffer>>bits)&255);}}
  return decodeURIComponent(bytes.map(b=>'%'+b.toString(16).padStart(2,'0')).join(''));
}

function qqComicContent(input) {
  if(input.chapter.isLocked)throw new Error('Authorization required');
  const html=host.get(input.chapter.url).body,encoded=html.match(/var\s+DATA\s*=\s*'([^']+)'/);
  const assignments=Array.from(html.matchAll(/window\s*\[\s*((?:["'][a-z]+["']\s*\+?\s*)+)\]\s*=\s*([^;]+);/g))
    .filter(match=>Array.from(match[1].matchAll(/["']([a-z]+)["']/g)).map(piece=>piece[1]).join('')==='nonce');
  if(!encoded || !assignments.length)throw new Error('Missing comic payload');
  let expression=assignments[assignments.length-1][2].replace(/\(\+eval\("([^"]+)"\)\)\.toString\(\)/g,(_,math)=>JSON.stringify(String(comicArithmetic(math))));
  const pieces=expression.split(/\s*\+\s*/).map(piece=>{const literal=piece.trim().match(/^(['"])([a-zA-Z0-9]*)\1$/);if(!literal)throw new Error('Unsupported image data key');return literal[2];});
  const offsets=pieces.join('').match(/\d+[a-zA-Z]+/g),chars=encoded[1].split('');
  if(!offsets?.length)throw new Error('Invalid image data key');
  for(const segment of offsets.reverse())chars.splice(parseInt(segment,10)&255,segment.replace(/\d+/g,'').length);
  const data=JSON.parse(comicBase64(chars.join('')));
  if(!data.chapter?.canRead || Number(data.chapter.vipStatus)===2)throw new Error('Authorization required');
  if(!data.picture?.length)throw new Error('Missing comic images');
  return {title:data.chapter.cTitle||input.chapter.title,images:data.picture.map(image=>({url:host.url(image.url,input.chapter.url),width:image.width,height:image.height}))};
}

// Execution only. Requests, selectors, pagination and filters live in source-definitions.js.
function sourceTemplate(template, values, encode = true) {
  return template.replace(/\{([A-Za-z]\w*)\}/g, (_, key) => {
    if (values[key] === undefined) throw new Error('Missing source parameter: ' + key);
    const value = String(values[key]);
    return encode && key !== 'homepage' ? encodeURIComponent(value) : value;
  });
}

function sourceConditions(when, values) {
  return Object.entries(when || {}).every(([key, value]) => values[key] === value);
}

function catalogResponse(url, body, headers = {}, validateResponse = true) {
  const response = body === undefined ? host.request({url, headers}) : host.request({
    url, method: 'POST', headers: {...headers, 'Content-Type': 'application/x-www-form-urlencoded'}, body
  });
  if (!validateResponse) return response;
  if (response.status === 403 || catalogDefaults.verificationTitlePattern.test(response.body)) {
    throw new Error('NORI_SITE_VERIFICATION_REQUIRED');
  }
  if (response.status !== 200 || !response.body.trim()) throw new Error('NORI_SEARCH_UNAVAILABLE');
  return response;
}

function sourceRequest(site, definition, parameters, cursor) {
  const request = Array.isArray(definition) ? definition.find(rule => sourceConditions(rule.when, parameters)) : definition;
  const values = {...parameters, homepage: site.homepage};
  for (const [key, mapping] of Object.entries(request.values || {})) {
    if (Object.hasOwn(mapping, values[key])) values[key] = mapping[values[key]];
  }
  const url = cursor || sourceTemplate(request.url, values);
  const body = !cursor && request.method === 'POST'
    ? Object.entries(request.form).map(([key, value]) => encodeURIComponent(key) + '=' + encodeURIComponent(sourceTemplate(value, values, false))).join('&')
    : undefined;
  return catalogResponse(url, body, request.headers || {}, request.validateResponse !== false);
}

function catalogParameters(site, input, searching) {
  const definitions = site.catalog ? (searching ? site.catalog.searchFilters : site.catalog.filters) : [];
  const filters = Object.fromEntries(definitions.map(filter => [filter.id, filter.defaultValue]));
  const page = Number(input.page || 1);
  return {...filters, ...input.filters, homepage: site.homepage, query: input.query || '', page, pageIndex: page - 1,
    offset: (page - 1) * (site.search?.pageSize || 1) + 1};
}

function catalogBooks(site, response, rule) {
  const rows = host.select(response.body, rule.items, rule.fields).map(row => {
    if (rule.fullTitlePattern) row.title = row.fullTitle.match(rule.fullTitlePattern)?.[1] || row.title;
    if (rule.titlePattern) row.title = row.title.replace(rule.titlePattern, '');
    if (rule.coverPattern) row.cover = row.coverStyle.match(rule.coverPattern)?.[2] || '';
    row.attributes = (rule.attributes || []).flatMap(attribute => {
      const raw = row[attribute.field] || '';
      const value = attribute.pattern ? raw.match(attribute.pattern)?.[1] : raw;
      return value?.trim() ? [{name: attribute.name, value: value.trim()}] : [];
    });
    return row;
  });
  return uniqueBooks(site, rows, response.url);
}

function catalogPageNumber(url, pattern) {
  return Number((pattern && String(url).match(pattern) || String(url).match(catalogDefaults.defaultPagePattern))?.[1] || 1);
}

function catalogNext(response, rule) {
  if (rule.mode === 'none') return null;
  const links = host.select(response.body, catalogDefaults.links.items, catalogDefaults.links.fields);
  if (rule.mode === 'next') {
    const next = links.find(link => link.text === rule.label);
    return next ? host.url(next.href, response.url) : null;
  }
  const page = catalogPageNumber(response.url, rule.pagePattern);
  const next = links.find(link => link.text === String(page + 1) || link.text === '第 ' + (page + 1) + ' 页')
    || links.find(link => catalogDefaults.nextPagePattern.test(link.text.trim()));
  return next ? host.url(next.href, response.url) : null;
}

function catalogEncodedQuery(query, encoding) {
  const alphabet = encoding.alphabet;
  const randomCharacter = () => alphabet[Math.floor(Math.random() * alphabet.length)];
  return Array.from(encodeURI(query), character => {
    const index = alphabet.indexOf(character);
    const encoded = index < 0 ? character : alphabet[(index + encoding.shift) % alphabet.length];
    return randomCharacter() + encoded + randomCharacter();
  }).join('');
}

function catalogHTML(response, rule) {
  if (!rule) return response;
  const callback = rule.callback.replace(/[\\^$.*+?()[\]{}|]/g, '\\$&');
  const payload = response.body.match(new RegExp('^\\s*' + callback + '\\(([\\s\\S]*)\\);?\\s*$'));
  if (!payload) throw new Error('Invalid search response');
  const result = JSON.parse(payload[1]);
  if (result[rule.statusField] !== rule.successValue || typeof result[rule.htmlField] !== 'string') {
    throw new Error('NORI_SEARCH_UNAVAILABLE');
  }
  return {...response, body: result[rule.htmlField]};
}

function websiteCatalog(input) {
  const site = website(input.siteID);
  const searching = typeof input.query === 'string' && input.query.trim().length > 0;
  const rule = searching ? site.catalog.search : site.catalog.library;
  if (!rule) throw new Error('NORI_SEARCH_UNAVAILABLE');
  const parameters = catalogParameters(site, input, searching);
  const sectionRule = rule.sections?.find(section => sourceConditions(section.when, parameters));
  if (sectionRule && !input.cursor) {
    const section = websiteHome(input).find(section => section.id === sectionRule.id);
    return {books: section.books, title: section.title, nextCursor: null};
  }
  if (rule.queryEncoding) parameters.encodedQuery = catalogEncodedQuery(input.query, rule.queryEncoding);
  if (rule.preflight && !input.cursor) sourceRequest(site, rule.preflight, parameters);
  let response = sourceRequest(site, rule.request, parameters, input.cursor);
  if (rule.verificationPattern?.test(response.body)) throw new Error('NORI_SITE_VERIFICATION_REQUIRED');
  if (rule.requireAny && !rule.requireAny.some(text => response.body.includes(text))) throw new Error('NORI_SEARCH_UNAVAILABLE');
  response = catalogHTML(response, rule.response);
  let books = catalogBooks(site, response, rule.rows);
  if (!books.length && rule.fallbackRows) books = catalogBooks(site, response, rule.fallbackRows);
  return {books, nextCursor: catalogNext(response, rule.pagination), title: ''};
}

function publicCatalogFilter(filter) {
  const {optionsSource, defaultSetting, ...definition} = filter;
  return definition;
}

function websiteCatalogFilters(input) {
  const site = website(input.siteID);
  const filters = input.query ? site.catalog.searchFilters : site.catalog.filters;
  return filters.map(filter => {
    let options = filter.options;
    if (filter.optionsSource) {
      const rule = filter.optionsSource;
      const parameters = catalogParameters(site, input, false);
      const response = sourceRequest(site, rule.request, parameters);
      options = [...rule.initialOptions];
      const seen = new Set(options.map(option => option.value));
      for (const link of host.select(response.body, rule.items, rule.fields)) {
        const value = link.href.match(rule.valuePattern)?.[1];
        if (!value || seen.has(value)) continue;
        seen.add(value);
        options.push({value, title: link.title.replace(rule.titlePattern, '')});
      }
      if (options.length < rule.minimumOptions) throw new Error('Missing category navigation');
    }
    return {...publicCatalogFilter(filter), options,
      defaultValue: filter.defaultSetting ? input.settings?.[filter.defaultSetting] || filter.defaultValue : filter.defaultValue};
  });
}

// Execution only. Each website declares its reading and request rules above.
function novelReadingURL(path,base) {
  // These sites publish HTTP links even on their verified HTTPS pages.
  return host.url(String(path||'').replace(/^http:/i,'https:'),base);
}
function novelReadingResponse(siteID,url) {
  const headers=website(siteID).reading.headers;
  return catalogResponse(url,undefined,headers);
}
function novelReadingLinks(response,selector) {
  return host.select(response.body,selector,{title:{selector:''},href:{selector:'',attribute:'href'}})
    .map(row=>({title:row.title,url:novelReadingURL(row.href,response.url)})).filter(row=>row.url);
}
function novelDirectoryChapters(response,rule,detail=false) {
  const seen=new Set();
  const chapters=novelReadingLinks(response,detail?(rule.detailToc||rule.toc):rule.toc)
    .filter(row=>row.title&&!seen.has(row.url)&&seen.add(row.url))
    .map(row=>({title:row.title,url:row.url,isLocked:false}));
  if(!chapters.length)throw new Error('Missing chapter directory');
  return chapters;
}
function novelDirectoryNext(response,rule,detail=false) {
  if(rule.tocPaging==='links') {
    const current=Number(response.url.match(readingDefaults.directoryPagePattern)?.[1]||1);
    const links=novelReadingLinks(response,readingDefaults.directoryLinks);
    return links.find(row=>row.title===String(current+1))?.url||null;
  }
  if(rule.tocPaging!=='select')return null;
  // The same page selector appears above and below the directory.
  const options=Array.from(new Set(host.select(response.body,readingDefaults.directoryOptions.items,readingDefaults.directoryOptions.fields)
    .map(row=>novelReadingURL(row.href,response.url)).filter(Boolean)));
  if(options.length) {
    const current=options.indexOf(response.url);
    if(current<0)throw new Error('Chapter directory page is not in the page selector');
    return options[current+1]||null;
  }
  return detail&&!rule.separateDirectory?novelReadingLinks(response,rule.directoryLink)[0]?.url||null:null;
}
function novelReadingMetadata(book,response,rule) {
  const fields=rule.metadata||readingDefaults.metadata;
  const info=host.select(response.body,fields.items,fields.fields)[0];
  return {...book,title:info.title||info.heading||book.title,author:info.author||info.plainAuthor||book.author,
    summary:info.summary||info.intro||info.description||book.summary,
    coverURL:novelReadingURL(info.cover||info.plainCover,response.url)||book.coverURL,
    attributes:(rule.attributes||readingDefaults.attributes).filter(attribute=>info[attribute.field])
      .map(attribute=>({name:attribute.name,value:info[attribute.field]}))};
}

function novelDetail(input,site) {
  const rule=site.reading;
  const response=novelReadingResponse(input.siteID,input.book.detailURL);
  const book=novelReadingMetadata(input.book,response,rule);
  let directory=response;
  if(rule.separateDirectory) {
    const url=novelReadingLinks(response,rule.directoryLink)[0]?.url;
    if(!url)throw new Error('Missing chapter directory link');
    directory=novelReadingResponse(input.siteID,url);
  }
  return {book,chapters:novelDirectoryChapters(directory,rule,true),
    nextChapterCursor:novelDirectoryNext(directory,rule,true)};
}
function novelChapters(input) {
  const rule=website(input.siteID).reading;
  if(rule?.engine!=='paged')throw new Error('Unsupported chapter directory');
  const response=novelReadingResponse(input.siteID,input.cursor);
  return {chapters:novelDirectoryChapters(response,rule),nextCursor:novelDirectoryNext(response,rule)};
}

function novelBase64Text(value) {
  const alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  const bytes=[];let buffer=0,bits=0;
  for(const char of value.replace(/=+$/,'')) {
    const digit=alphabet.indexOf(char);
    if(digit<0)throw new Error('Invalid encoded chapter text');
    buffer=(buffer<<6)|digit;bits+=6;
    if(bits>=8){bits-=8;bytes.push((buffer>>>bits)&255);}
  }
  return decodeURIComponent(bytes.map(byte=>'%'+byte.toString(16).padStart(2,'0')).join(''));
}
function novelDecodedHTML(html) {
  // Only constant qsbs.bb text payloads are decoded. Unrelated scripts, eval and obfuscated code remain inert.
  return html.replace(/<script\b[^>]*>\s*document\.writeln\s*\(\s*qsbs\.bb\(\s*(['"])([A-Za-z0-9+/=]+)\1\s*\)\s*\)\s*;?\s*<\/script\s*>/gi,
    (_,quote,value)=>novelBase64Text(value));
}
function novelNextContent(response,rule) {
  if(rule.nextVariable) {
    const literal=response.body.match(rule.nextVariablePattern||readingDefaults.nextVariablePattern);
    if(!literal)throw new Error('Missing chapter navigation');
    return novelReadingURL(literal[2],response.url);
  }
  const links=novelReadingLinks(response,rule.next);
  return links.find(link=>/下一[页章]/.test(link.title))?.url||null;
}
function novelContent(input,site) {
  const rule=site.reading;
  const pattern=rule.chapterPattern||readingDefaults.chapterPattern;
  const original=input.chapter.url.match(pattern);
  if(!original)throw new Error('Invalid chapter address');
  const visited=new Set(),paragraphs=[];
  let url=input.chapter.url;
  for(let page=0;page<12;page++) {
    if(visited.has(url))throw new Error('Chapter continuation loop');
    visited.add(url);
    const response=novelReadingResponse(input.siteID,url);
    const html=rule.encoded?novelDecodedHTML(response.body):response.body;
    const content=host.content(html,{chapterItems:rule.toc,chapterTitle:{selector:''},chapterLink:{selector:'',attribute:'href'},
      content:rule.content,remove:rule.remove||readingDefaults.remove},response.url);
    paragraphs.push(...content.paragraphs.filter(text=>{
      const value=text.trim().normalize('NFKC');
      return value&&!(rule.ignoredParagraphs||readingDefaults.ignoredParagraphs).some(pattern=>pattern.test(value));
    }));
    const next=novelNextContent(response,rule),continuation=next?.match(pattern);
    if(!continuation||continuation[1]!==original[1]) {
      if(!paragraphs.length)throw new Error('Missing chapter content');
      return {title:input.chapter.title,paragraphs};
    }
    url=next;
  }
  throw new Error('Chapter exceeds the page request limit');
}

// Execution only. Provider endpoints and account metadata are declared above.
function driveList(input) {
  if(input.providerID==='baidu')return baiduList(input);
  if(input.providerID!=='quark')throw new Error('Unsupported drive');
  const page=Number(input.cursor||'1');
  const rule=driveRules.quark;
  const url=rule.apiBase+rule.routes.list+'?'+queryString({...rule.parameters,pdir_fid:input.folder||rule.root,
    _page:page,_size:100,_fetch_total:1,_sort:'file_type:asc,file_name:asc'});
  const response=host.request({url,headers:rule.headers});
  if(response.status===401 || response.status===403)throw new Error('NORI_AUTH_REQUIRED');
  const result=JSON.parse(response.body);
  if([31001,32001].includes(result.code))throw new Error('NORI_AUTH_REQUIRED');
  if(result.code!==0 || !result.data || !Array.isArray(result.data.list))throw new Error('Drive login or response invalid');
  return {files:result.data.list.map(f=>({id:f.fid,name:f.file_name,isDirectory:!f.file,size:f.size||null})),
    cursor:page*100<(result.metadata?._total||0)?String(page+1):null};
}

function driveResolve(input) {
  if(input.providerID==='baidu')return baiduResolve(input);
  const rule=driveRules.quark;
  const response=host.request({url:rule.apiBase+rule.routes.download+'?'+queryString(rule.parameters),
    method:'POST',headers:{...rule.headers,'Content-Type':'application/json'},body:JSON.stringify({fids:[input.file.id]})});
  if(response.status===401 || response.status===403)throw new Error('NORI_AUTH_REQUIRED');
  const result=JSON.parse(response.body);
  const file=result.data?.[0];
  if(result.code!==0 || !file?.download_url)throw new Error('File download unavailable');
  return {url:file.download_url,headers:{Referer:rule.headers.Referer}};
}

function baiduGet(path) {
  const response=host.request({url:driveRules.baidu.webBase+path,headers:driveRules.baidu.headers});
  if(response.status===401 || response.status===403)throw new Error('NORI_AUTH_REQUIRED');
  const result=JSON.parse(response.body);
  if([-6,-9,111,112].includes(result.errno))throw new Error('NORI_AUTH_REQUIRED');
  if(result.errno!==0)throw new Error('Baidu request failed');
  return result;
}
function baiduList(input) {
  const page=Number(input.cursor||'1');
  const folder=input.folder?.startsWith('{')?JSON.parse(input.folder).path:(input.folder||'/');
  const result=baiduGet(driveRules.baidu.routes.list+'?web=1&app_id='+driveRules.baidu.appID+'&order=name&desc=0&num=100&page='+page+'&dir='+encodeURIComponent(folder));
  const list=result.list||[];
  return {files:list.map(f=>({id:JSON.stringify({id:f.fs_id,path:f.path}),name:f.server_filename,isDirectory:f.isdir===1,size:f.size||null})),
    cursor:list.length===100?String(page+1):null};
}
function base64Binary(text) {
  const alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';let out='';
  for(let i=0;i<text.length;i+=3){
    const a=text.charCodeAt(i)&255,b=text.charCodeAt(i+1)&255,c=text.charCodeAt(i+2)&255;
    out+=alphabet[a>>2]+alphabet[((a&3)<<4)|(b>>4)]+(i+1<text.length?alphabet[((b&15)<<2)|(c>>6)]:'=')+(i+2<text.length?alphabet[c&63]:'=');
  }
  return out;
}
function baiduResolve(input) {
  const file=JSON.parse(input.file.id);
  const fields=encodeURIComponent(JSON.stringify(['sign1','sign2','sign3','timestamp']));
  const result=baiduGet(driveRules.baidu.routes.variables+'?web=1&app_id='+driveRules.baidu.appID+'&fields='+fields).result;
  if(!result || typeof result.sign2!=='string')throw new Error('Missing download signature');
  // The provider supplies this signer to its own web client. It runs in this bounded VM.
  const signer=Function('"use strict"; return ('+result.sign2+');')();
  if(typeof signer!=='function')throw new Error('Invalid download signature');
  const sign=base64Binary(signer(result.sign3,result.sign1));
  const download=baiduGet(driveRules.baidu.routes.download+'?type=dlink&web=1&app_id='+driveRules.baidu.appID+'&fidlist='+encodeURIComponent(JSON.stringify([file.id]))
    +'&sign='+encodeURIComponent(sign)+'&timestamp='+encodeURIComponent(result.timestamp));
  const url=download.dlink?.[0]?.dlink;
  if(!url)throw new Error('File download unavailable');
  return {url,headers:driveRules.baidu.downloadHeaders};
}

// Sharing and account-file access are separate provider operations.
function queryString(values) {
  return Object.keys(values).filter(k=>values[k]!==null && values[k]!==undefined).map(k=>encodeURIComponent(k)+'='+encodeURIComponent(values[k])).join('&');
}
function quarkAPI(path, body, stage) {
  const response=host.request({url:driveRules.quark.apiBase+path+(path.includes('?')?'&':'?')+queryString(driveRules.quark.parameters),
    method:body?'POST':'GET',headers:{...driveRules.quark.headers,'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});
  if([401,403].includes(response.status))throw new Error('NORI_AUTH_REQUIRED');
  const result=JSON.parse(response.body);
  if([31001,32001].includes(result.code))throw new Error('NORI_AUTH_REQUIRED');
  if(result.code!==0) {
    const message=result.message||'';
    if(/captcha|验证/i.test(message))throw new Error('NORI_VERIFICATION_REQUIRED');
    if((stage==='code'||stage==='needCode') && /提取|密码|passcode/i.test(message))throw new Error(stage==='needCode'?'NORI_CODE_REQUIRED':'NORI_CODE_INVALID');
    throw new Error(['share','code','needCode'].includes(stage)?'NORI_SHARE_UNAVAILABLE':'NORI_TRANSFER_FAILED');
  }
  return result;
}
function ownQuarkFile(f) {return {id:String(f.fid),name:f.file_name,isDirectory:!f.file,size:f.size||null};}
function ownBaiduFile(f) {return {id:JSON.stringify({id:f.fs_id,path:f.path}),name:f.server_filename,isDirectory:f.isdir===1,size:f.size||null};}
function quarkShareList(input) {
  let ctx=input.context?JSON.parse(input.context):null;
  const pwdID=input.share.url.split('/s/')[1];
  if(!ctx || ctx.pwdID!==pwdID) {
    const result=quarkAPI(driveRules.quark.routes.shareToken,{pwd_id:pwdID,passcode:input.share.accessCode||''},input.share.accessCode?'code':'needCode');
    if(!result.data?.stoken)throw new Error(input.share.accessCode?'NORI_CODE_INVALID':'NORI_CODE_REQUIRED');
    ctx={pwdID,stoken:result.data.stoken,tokens:{}};
  }
  const page=Number(input.cursor||1);
  const result=quarkAPI(driveRules.quark.routes.shareDetail+'?'+queryString({pwd_id:ctx.pwdID,stoken:ctx.stoken,pdir_fid:input.folder||'0',
    _page:page,_size:100,_fetch_total:1,_fetch_share:0,force:0,_sort:'file_type:asc,file_name:asc'}),null,'share');
  if(!Array.isArray(result.data?.list))throw new Error('NORI_SHARE_UNAVAILABLE');
  const files=result.data.list.map(f=>{ctx.tokens[String(f.fid)]=f.share_fid_token;return ownQuarkFile(f);});
  return {files,cursor:page*100<(result.metadata?._total||0)?String(page+1):null,context:JSON.stringify(ctx)};
}
function baiduShareRequest(path,body) {
  const response=host.request({url:driveRules.baidu.webBase+path,method:body?'POST':'GET',
    headers:driveRules.baidu.shareHeaders,
    body:body?queryString(body):undefined});
  if([401,403].includes(response.status))throw new Error('NORI_AUTH_REQUIRED');
  const result=JSON.parse(response.body);
  if(result.errno===-6)throw new Error('NORI_AUTH_REQUIRED');
  if([4,20,62].includes(result.errno))throw new Error('NORI_VERIFICATION_REQUIRED');
  return result;
}
function baiduShareList(input) {
  let ctx=input.context?JSON.parse(input.context):null;
  const surl=input.share.url.split('/s/1')[1];
  if(!ctx || ctx.surl!==surl) {
    let response=host.get(input.share.url), sekey='';
    if(input.share.accessCode) {
      const verified=baiduShareRequest(driveRules.baidu.routes.verify+'?'+queryString({surl,channel:'chunlei',clienttype:0,web:1,app_id:driveRules.baidu.appID}),
        {pwd:input.share.accessCode,vcode:'',vcode_str:''});
      if(verified.errno===-9)throw new Error('NORI_CODE_INVALID');
      if(verified.errno!==0 || !verified.randsk)throw new Error('NORI_SHARE_UNAVAILABLE');
      sekey=decodeURIComponent(verified.randsk);
      response=host.get(input.share.url);
    }
    const shareID=response.body.match(/["']?shareid["']?\s*[:=]\s*["']?(\d+)/i);
    const uk=response.body.match(/["']?(?:share_uk|shareuk)["']?\s*[:=]\s*["']?(\d+)/i);
    if(!shareID || !uk) {
      if(!input.share.accessCode && /提取码|access-code|share\/init/.test(response.body+response.url))throw new Error('NORI_CODE_REQUIRED');
      throw new Error('NORI_SHARE_UNAVAILABLE');
    }
    ctx={surl,shareID:shareID[1],uk:uk[1],sekey};
  }
  const page=Number(input.cursor||1),folder=input.folder?JSON.parse(input.folder).path:null;
  const result=baiduShareRequest(driveRules.baidu.routes.shareList+'?'+queryString({shareid:ctx.shareID,uk:ctx.uk,sekey:ctx.sekey,type:0,root:folder?0:1,
    dir:folder,page,num:100,order:'name',desc:0,channel:'chunlei',web:1,clienttype:0,app_id:driveRules.baidu.appID}));
  if(result.errno===-9)throw new Error(input.share.accessCode?'NORI_CODE_INVALID':'NORI_CODE_REQUIRED');
  if(result.errno!==0 || !Array.isArray(result.list))throw new Error('NORI_SHARE_UNAVAILABLE');
  return {files:result.list.map(ownBaiduFile),cursor:result.list.length===100?String(page+1):null,context:JSON.stringify(ctx)};
}
function driveShareList(input) {
  if(input.providerID==='quark')return quarkShareList(input);
  if(input.providerID==='baidu')return baiduShareList(input);
  throw new Error('Unsupported share provider');
}
function completed(file) {return {status:'completed',file,taskID:null};}
function pending(job) {return {status:'pending',file:null,taskID:JSON.stringify(job)};}
function quarkTransfer(input) {
  const ctx=JSON.parse(input.context),path='/随阅/'+input.destinationKey;
  const found=quarkAPI(driveRules.quark.routes.pathInfo,{file_path:[path],namespace:'0'});
  let folder=found.data?.[0]?.fid;
  if(!folder)folder=quarkAPI(driveRules.quark.routes.create,{pdir_fid:'0',file_name:'',dir_path:path,dir_init_lock:false}).data?.fid;
  if(!folder)throw new Error('NORI_TRANSFER_FAILED');
  const existing=quarkAPI(driveRules.quark.routes.list+'?'+queryString({pdir_fid:folder,_page:1,_size:100,_sort:'file_name:asc'})).data?.list||[];
  const cached=existing.find(f=>f.file && f.file_name===input.file.name && (!input.file.size || Number(f.size)===input.file.size));
  if(cached)return completed(ownQuarkFile(cached));
  const token=ctx.tokens[input.file.id];
  if(!token)throw new Error('NORI_SHARE_UNAVAILABLE');
  const result=quarkAPI(driveRules.quark.routes.save,{fid_list:[input.file.id],fid_token_list:[token],to_pdir_fid:String(folder),
    pwd_id:ctx.pwdID,stoken:ctx.stoken,pdir_fid:'0',scene:'link'});
  if(!result.data?.task_id)throw new Error('NORI_TRANSFER_FAILED');
  return pending({providerID:'quark',id:result.data.task_id,name:input.file.name,size:input.file.size});
}
function baiduToken() {
  const fields=encodeURIComponent(JSON.stringify(['bdstoken']));
  const result=baiduGet(driveRules.baidu.routes.variables+'?web=1&app_id='+driveRules.baidu.appID+'&fields='+fields);
  if(!result.result?.bdstoken)throw new Error('NORI_AUTH_REQUIRED');
  return result.result.bdstoken;
}
function baiduEnsureFolder(parent,name,token) {
  const existing=baiduGet(driveRules.baidu.routes.list+'?'+queryString({dir:parent,num:100,page:1,order:'name',web:1,app_id:driveRules.baidu.appID})).list||[];
  const folder=existing.find(f=>f.isdir===1 && f.server_filename===name);
  if(folder)return folder.path;
  const path=parent.replace(/\/$/,'')+'/'+name;
  const result=baiduShareRequest(driveRules.baidu.routes.create+'?'+queryString({a:'commit',web:1,app_id:driveRules.baidu.appID,bdstoken:token}),
    {path,isdir:1,block_list:'[]',rtype:0});
  if(result.errno!==0 && result.errno!==-8)throw new Error('NORI_TRANSFER_FAILED');
  return path;
}
function baiduTransfer(input) {
  const ctx=JSON.parse(input.context), token=baiduToken();
  const root=baiduEnsureFolder('/','随阅',token),folder=baiduEnsureFolder(root,input.destinationKey,token);
  const existing=baiduGet(driveRules.baidu.routes.list+'?'+queryString({dir:folder,num:100,page:1,web:1,app_id:driveRules.baidu.appID})).list||[];
  const cached=existing.find(f=>f.isdir===0 && f.server_filename===input.file.name && (!input.file.size || Number(f.size)===input.file.size));
  if(cached)return completed(ownBaiduFile(cached));
  const file=JSON.parse(input.file.id);
  const result=baiduShareRequest(driveRules.baidu.routes.transfer+'?'+queryString({shareid:ctx.shareID,from:ctx.uk,sekey:ctx.sekey,bdstoken:token,
    channel:'chunlei',clienttype:0,web:1,app_id:driveRules.baidu.appID}),{path:folder,async:2,fsidlist:JSON.stringify([file.id]),type:0,ondup:'fail'});
  if(result.errno!==0)throw new Error('NORI_TRANSFER_FAILED');
  return pending({providerID:'baidu',id:result.taskid||null,folder,name:input.file.name,size:input.file.size});
}
function driveTransfer(input) {
  if(input.providerID==='quark')return quarkTransfer(input);
  if(input.providerID==='baidu')return baiduTransfer(input);
  throw new Error('Unsupported share provider');
}
function driveTransferStatus(input) {
  const job=JSON.parse(input.taskID);
  if(input.providerID!==job.providerID)throw new Error('NORI_TRANSFER_FAILED');
  if(job.providerID==='quark') {
    const result=quarkAPI(driveRules.quark.routes.task+'?'+queryString({task_id:job.id,retry_index:0}));
    if(result.data?.status===2) {
      const fid=result.data.save_as?.save_as_top_fids?.[0];
      if(!fid)throw new Error('NORI_TRANSFER_FAILED');
      return completed({id:String(fid),name:job.name,isDirectory:false,size:job.size});
    }
    if(result.data?.status===3 || result.data?.status===4)throw new Error('NORI_TRANSFER_FAILED');
    return pending(job);
  }
  const result=baiduGet(driveRules.baidu.routes.list+'?'+queryString({dir:job.folder,num:100,page:1,web:1,app_id:driveRules.baidu.appID}));
  const file=(result.list||[]).find(f=>f.isdir===0 && f.server_filename===job.name && (!job.size || Number(f.size)===job.size));
  return file?completed(ownBaiduFile(file)):pending(job);
}
